import React, { useContext, useEffect, useState } from 'react';
import { useIntl } from 'react-intl';

import { CodeIcon, CodeOffIcon } from '@dynatrace/strato-icons';

import { Button } from '../../buttons/button/Button.js';
import { Tooltip } from '../../overlays/tooltip/Tooltip.js';
import { DataTableContext } from '../contexts/DataTableContext.js';
import { dataTableMessages } from '../DataTable/messages.js';
import { areAllColumnsFontStyleCode } from '../utils/fontstyle-utils.js';

/**
 * DataTable toolbar button for setting font style for the data table.
 *
 * @returns FontStyle component
 */
export const FontStyle = () => {
  const { instanceColumns, variant, onDataTableFontStyleChange } =
    useContext(DataTableContext);

  const intl = useIntl();

  const fontStyleCodeLabel = intl.formatMessage(
    dataTableMessages.fontStyleCodeLabel,
  );
  const fontStyleTextLabel = intl.formatMessage(
    dataTableMessages.fontStyleTextLabel,
  );

  const [fontStyle, setFontStyle] = useState<'text' | 'code' | undefined>(
    variant.fontStyle,
  );

  const fontStyleLabel =
    fontStyle === 'text' ? fontStyleCodeLabel : fontStyleTextLabel;

  const allColumnsAreCode = areAllColumnsFontStyleCode(instanceColumns ?? []);

  // update menu labels/icons appropriately when variant changes
  useEffect(() => {
    let newFontStyle =
      variant.fontStyle === undefined ? 'text' : variant.fontStyle;
    newFontStyle =
      newFontStyle === 'text' && !allColumnsAreCode ? 'text' : 'code';

    setFontStyle(newFontStyle);
  }, [variant.fontStyle, allColumnsAreCode]); // update only when variant or all columns font style changes

  const updateFontStyle = () => {
    const newFontStyle = fontStyle === 'text' ? 'code' : 'text';
    setFontStyle(newFontStyle);
    if (onDataTableFontStyleChange) {
      onDataTableFontStyleChange(newFontStyle);
    }
  };

  return (
    <Tooltip text={fontStyleLabel}>
      <Button aria-label={fontStyleLabel} onClick={updateFontStyle}>
        {fontStyle === 'text' && (
          <Button.Prefix>
            <CodeIcon />
          </Button.Prefix>
        )}
        {fontStyle === 'code' && (
          <Button.Suffix>
            <CodeOffIcon />
          </Button.Suffix>
        )}
      </Button>
    </Tooltip>
  );
};

FontStyle.displayName = 'DataTable.FontStyle';
